/* ===================================================================== Motion Grammar
   smooth  = continuous easing
   stepped = poses held on twos: 12 drawings/s, each pose 83.33ms
   cut     = instant, editorial hard cut */
.f12-m-smooth {
  --f-rng-ind-transition: transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1), width 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
  --f-switch-thumb-transition: inset-inline-start 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
  --f-skeleton-animation: f12SkeletonSmooth 1400ms ease-in-out infinite;
  --f-enter-animation: f12EnterSmooth 260ms cubic-bezier(0.2, 0.8, 0.2, 1);
  --f-pop-animation: f12PopSmooth 240ms cubic-bezier(0.2, 0.9, 0.3, 1.25);
  --f-burst-animation: f12BurstSmooth 320ms ease-out;
}
.f12-m-stepped {
  --f-rng-ind-transition: transform 250ms steps(3, end), width 250ms steps(3, end);
  --f-switch-thumb-transition: inset-inline-start 250ms steps(3, end);
  --f-skeleton-animation: f12SkeletonStep 333ms steps(4, end) infinite;
  --f-enter-animation: f12EnterStep 250ms step-end;
  --f-pop-animation: f12PopStep 333ms step-end;
  --f-burst-animation: f12BurstStep 250ms step-end;
}
.f12-m-cut {
  --f-rng-ind-transition: none;
  --f-switch-thumb-transition: none;
  --f-skeleton-animation: none;
  --f-enter-animation: none;
  --f-pop-animation: none;
  --f-burst-animation: none;
}
.f12-rng-ind {
  transition: var(--f-rng-ind-transition, none);
}
.f12-switch-thumb {
  transition: var(--f-switch-thumb-transition, none);
}
.f12-skeleton-animated {
  animation: var(--f-skeleton-animation, f12SkeletonStep 333ms steps(4, end) infinite);
}
@keyframes f12SkeletonSmooth {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.55;
  }
}
@keyframes f12SkeletonStep {
  0% {
    background-position: 0 0;
    opacity: 1;
  }
  50% {
    background-position: 6px 3px;
    opacity: 0.68;
  }
  100% {
    background-position: 12px 6px;
    opacity: 1;
  }
}

.f12-enter {
  animation: var(--f-enter-animation, none);
}
@keyframes f12EnterSmooth {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes f12EnterStep {
  0% {
    opacity: 0.35;
    transform: translateY(10px);
  }
  33% {
    opacity: 0.8;
    transform: translateY(4px);
  }
  66% {
    opacity: 1;
    transform: translateY(1px);
  }
  100% {
    opacity: 1;
    transform: none;
  }
}

.f12-pop {
  animation: var(--f-pop-animation, none);
}
@keyframes f12PopSmooth {
  from {
    opacity: 0;
    transform: scale(0.85);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes f12PopStep {
  0% {
    transform: scale(0.5);
  }
  25% {
    transform: scale(1.22);
  }
  50% {
    transform: scale(0.94);
  }
  75% {
    transform: scale(1);
  }
  100% {
    transform: none;
  }
}
.f12-pop .f12-burst {
