    );

    const ctxValue = React.useMemo<RadioGroupContextValue>(
      () => ({
        name,
        fallbackName,
        value: controlledValue,
        isControlled,
        defaultValue,
        disabled: effectiveDisabled,
        required: effectiveRequired,
        form,
        density: effectiveDensity,
        invalid: effectiveInvalid,
        onSelect: handleSelect,
