      [
        name,
        fallbackName,
        controlledValue,
        isControlled,
        defaultValue,
        effectiveDisabled,
        effectiveRequired,
        form,
        effectiveDensity,
        effectiveInvalid,
        handleSelect,
      ],
    );

    return (
      <RadioGroupContext.Provider value={ctxValue}>
        <fieldset
          ref={ref}
          id={groupId}
          role="radiogroup"
